import {ToolRegistry} from './src/orchestration/tools/registry.js';
import {setLogger} from './src/shared/logger.js';

async function run() {
  const recordedLogs = [];
  const logger = {
    debug: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
    info: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
    warn: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
    error: (cat, msg, fields) => recordedLogs.push(JSON.stringify({cat, msg, fields})),
  };
  setLogger(logger);
  const registry = new ToolRegistry();
  registry.register({
    name: 'ssn_lookup',
    description: 'Look up record by identifier',
    inputSchema: {
      type: 'object',
      properties: {ssn: {type: 'string'}},
      required: ['ssn']
    }
  }, async () => 'found');

  const response = await registry.execute('ssn_lookup', {ssn: 123456789});
  console.log(response);
  console.log(recordedLogs);
}
run();
EOF
node --experimental-specifier-resolution=node --loader ts-node/esm test-tmp.js

cat << 'EOF' >> src/orchestration/tools/registry.test.ts

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs])', async () => {
    const { setLogger } = await import('../../shared/logger.js');
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: any = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect(executorCalls).toBe(0);
    const resResult = (response as any).result;
    expect(resResult).toMatch(/ssn/);
    expect(resResult).toMatch(/string/);
    expect(resResult).not.toMatch(/123456789/);
    expect(recordedLogs.some(line => line.includes('123456789'))).toBe(false);

    setLogger(undefined); // cleanup
  });
EOF
